function seedGarden(seed){const r=rand(seed);const items=[];const placements=[['wavy',.26,.43,250],['bell',.57,.40,210],['toadstool',.76,.54,295],['ruffles',.43,.58,225],['curly',.17,.67,275],['twins',.6,.68,225],['toadstool',.86,.77,240],['bell',.37,.83,280],['wavy',.65,.93,290],['ruffles',.16,.91,195],['twins',.86,.94,165],['cat',.51,.91,175],['frog',.31,.64,130],['snail',.76,.90,135],['ghost',.46,.30,150],['bunny',.72,.72,150],['pumpkin',.45,.73,140]];for(const [id,x,y,size]of placements){const next=counter?catalog[Math.floor(r()*catalog.length)].id:id;const it=makeItem(next,(x+(r()-.5)*.025)*W,(y+(r()-.5)*.025)*H,size);it.flip=r()<.28;items.push(it);}return items;}
