function drawShootingStars(target,time=0,exporting=false){if(!state.shootingStars)return;for(let i=0;i<3;i++){const progress=exporting||reducedMotion?[.25,.54,.8][i]:((time/6000+i*.34)%1);target.save();target.globalAlpha=Math.max(.15,Math.sin(progress*Math.PI))*.9;drawSprite(target,'shooting-star',40+progress*(W+150),80+progress*450+i*85,155+i*22);target.restore();}}
function paintFrame(time=0){ctx.clearRect(0,0,W,H);ctx.drawImage(stillScene,0,0);drawShootingStars(ctx,time);if(keyboard){ctx.save();ctx.strokeStyle=palettes[state.palette].ink;ctx.lineWidth=2;ctx.setLineDash([7,7]);ctx.beginPath();ctx.arc(cursor.x,cursor.y,27,0,Math.PI*2);ctx.stroke();ctx.restore();}}
