function render(){if(!ready)return;draw(stillCtx,false);manageAnimation();$('#count').textContent=state.items.length+' little '+(state.items.length===1?'oddity':'oddities');$('#undo').disabled=!history.length;$('#clear').disabled=!state.items.length&&state.moon==='none'&&state.galaxy==='none'&&!state.shootingStars&&!state.weather.length;$('#paletteName').textContent=palettes[state.palette].name;document.querySelectorAll('[data-palette]').forEach(b=>{b.classList.toggle('active',b.dataset.palette===state.palette);b.setAttribute('aria-pressed',String(b.dataset.palette===state.palette));});$('#moon').value=state.moon;$('#galaxy').value=state.galaxy;$('#shootingStars').setAttribute('aria-pressed',String(state.shootingStars));document.querySelectorAll('[data-weather]').forEach(b=>b.setAttribute('aria-pressed',String(state.weather.includes(b.dataset.weather))));const phrases={nature:'A wild little corner to call your own.',ruins:'Some things get more interesting with age.',magic:'A little ritual. A little mystery.',plants:'Even the shadows like a little greenery.',mushrooms:'Mushrooms make excellent company.',animals:'All the best gardens have visitors.',spooky:'A little haunting is good for the soul.'};$('#caption').textContent=phrases[category];}
function choosePalette(key){if(!palettes[key])throw Error('Unknown palette');if(state.palette!==key){remember();state.palette=key;render();}return {palette:state.palette};}
function changeSky(moon,weather){const allowedMoons=['none','full','crescent','half','blood'],allowedWeather=['rain','snow','fog','lightning'];if(!allowedMoons.includes(moon)||!Array.isArray(weather)||weather.some(x=>!allowedWeather.includes(x)))throw Error('Invalid sky settings');remember();state.moon=moon;state.weather=[...new Set(weather)];render();return {moon:state.moon,weather:state.weather};}
