function clear(){if(!ready)return;remember();state.items=[];state.moon='none';state.galaxy='none';state.shootingStars=false;state.weather=[];render();notify('A clean patch. Undo brings it all back.');}
function save(){if(!ready)return;const out=document.createElement('canvas');out.width=W;out.height=H+130;const c=out.getContext('2d');c.fillStyle=palettes[state.palette].bg;c.fillRect(0,0,out.width,out.height);const art=document.createElement('canvas');art.width=W;art.height=H;draw(art.getContext('2d'));drawShootingStars(art.getContext('2d'),animationTime,true);c.drawImage(art,0,0);c.strokeStyle=palettes[state.palette].ink;c.lineWidth=1;c.beginPath();c.moveTo(50,H+12);c.lineTo(W-50,H+12);c.stroke();c.fillStyle=palettes[state.palette].ink;c.font='44px Georgia';c.fillText('Spooky Grove',50,H+78);c.font='18px Arial';c.textAlign='right';c.fillText('A LITTLE PLACE FOR STRANGE THINGS',W-50,H+71);out.toBlob(blob=>{if(!blob){notify('That picture couldn’t be saved. Please try again.');return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='spooky-grove.png';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);notify('Your garden picture is ready to save.');},'image/png');}
canvas.addEventListener('pointerup',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;const bounds=canvas.getBoundingClientRect();keyboard=false;stamp(selected,(e.clientX-bounds.left)/bounds.width*W,(e.clientY-bounds.top)/bounds.height*H);});
canvas.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Enter',' '].includes(e.key)){e.preventDefault();keyboard=true;if(e.key==='ArrowUp')cursor.y-=35;if(e.key==='ArrowDown')cursor.y+=35;if(e.key==='ArrowLeft')cursor.x-=35;if(e.key==='ArrowRight')cursor.x+=35;cursor.x=Math.max(30,Math.min(W-30,cursor.x));cursor.y=Math.max(100,Math.min(H-30,cursor.y));if(e.key==='Enter'||e.key===' ')stamp(selected,cursor.x,cursor.y);else render();}});canvas.addEventListener('blur',()=>{keyboard=false;render();});
document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.category;$('#itemSearch').value='';selected=catalog.find(v=>v.group===category).id;document.querySelectorAll('[data-category]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});renderSprites();render();}));
